
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE IF NOT EXISTS workspaces (id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,owner_id UUID NOT NULL,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,plan TEXT DEFAULT 'trial',trial_ends_at TIMESTAMPTZ,campaign_limit INTEGER DEFAULT 10,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS workspace_members (id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE,user_id UUID NOT NULL,role TEXT DEFAULT 'owner',created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS connected_accounts (id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE,platform TEXT NOT NULL,account_id TEXT NOT NULL,account_name TEXT NOT NULL,account_username TEXT NOT NULL,account_picture TEXT,access_token_encrypted TEXT NOT NULL,page_id TEXT,page_name TEXT,scopes TEXT[] DEFAULT '{}',is_active BOOLEAN DEFAULT true,created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(workspace_id,account_id));
CREATE TABLE IF NOT EXISTS campaigns (id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE,connected_account_id UUID REFERENCES connected_accounts(id) ON DELETE SET NULL,name TEXT NOT NULL,platform TEXT NOT NULL,status TEXT DEFAULT 'active',post_id TEXT,post_url TEXT,trigger_mode TEXT DEFAULT 'keyword',keywords TEXT[] DEFAULT '{}',exclude_keywords TEXT[] DEFAULT '{}',message_template TEXT NOT NULL,link_url TEXT NOT NULL,public_reply_text TEXT,delay_type TEXT DEFAULT 'random',one_time_per_user BOOLEAN DEFAULT true,follower_gate BOOLEAN DEFAULT false,cooldown_hours INTEGER DEFAULT 24,stats JSONB DEFAULT '{"comments_matched":0,"dms_sent":0,"dms_failed":0,"clicks":0}',created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS comments_log (id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,workspace_id UUID,campaign_id UUID,platform TEXT,comment_id TEXT UNIQUE NOT NULL,commenter_id TEXT,commenter_username TEXT,comment_text TEXT,post_id TEXT,matched BOOLEAN DEFAULT false,match_reason TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS dm_log (id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,workspace_id UUID,campaign_id UUID,platform TEXT,recipient_id TEXT,recipient_username TEXT,message_sent TEXT,success BOOLEAN DEFAULT false,meta_message_id TEXT,error_message TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS leads (id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,workspace_id UUID,campaign_id UUID,platform TEXT,user_id TEXT,username TEXT,email TEXT,whatsapp TEXT,source_comment TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS short_links (id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,workspace_id UUID,campaign_id UUID,slug TEXT UNIQUE NOT NULL,destination_url TEXT NOT NULL,clicks INTEGER DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS link_clicks (id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,short_link_id UUID,workspace_id UUID,ip_hash TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS subscriptions (id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,workspace_id UUID UNIQUE NOT NULL,plan TEXT NOT NULL,status TEXT DEFAULT 'active',billing_interval TEXT DEFAULT 'monthly',current_period_start TIMESTAMPTZ,current_period_end TIMESTAMPTZ,cancel_at_period_end BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments (id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,workspace_id UUID,razorpay_payment_id TEXT UNIQUE NOT NULL,razorpay_order_id TEXT,razorpay_signature TEXT,amount DECIMAL(10,2),currency TEXT DEFAULT 'INR',status TEXT DEFAULT 'captured',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS webhook_events (id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,event_id TEXT UNIQUE NOT NULL,event_type TEXT,payload JSONB,processed BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_campaigns_workspace ON campaigns(workspace_id);
CREATE INDEX IF NOT EXISTS idx_campaigns_post_id ON campaigns(post_id);
CREATE INDEX IF NOT EXISTS idx_dm_log_campaign_recipient ON dm_log(campaign_id,recipient_id);
CREATE INDEX IF NOT EXISTS idx_short_links_slug ON short_links(slug);
ALTER TABLE workspaces ENABLE ROW LEVEL SECURITY;ALTER TABLE campaigns ENABLE ROW LEVEL SECURITY;ALTER TABLE connected_accounts ENABLE ROW LEVEL SECURITY;ALTER TABLE comments_log ENABLE ROW LEVEL SECURITY;ALTER TABLE dm_log ENABLE ROW LEVEL SECURITY;ALTER TABLE leads ENABLE ROW LEVEL SECURITY;ALTER TABLE short_links ENABLE ROW LEVEL SECURITY;ALTER TABLE subscriptions ENABLE ROW LEVEL SECURITY;ALTER TABLE payments ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION get_my_workspace_ids() RETURNS SETOF UUID AS $$ SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid() $$ LANGUAGE SQL SECURITY DEFINER STABLE;
CREATE POLICY "own_workspaces" ON workspaces FOR ALL USING (owner_id=auth.uid() OR id IN (SELECT get_my_workspace_ids()));
CREATE POLICY "workspace_campaigns" ON campaigns FOR ALL USING (workspace_id IN (SELECT get_my_workspace_ids()));
CREATE POLICY "workspace_accounts" ON connected_accounts FOR ALL USING (workspace_id IN (SELECT get_my_workspace_ids()));
CREATE POLICY "workspace_comments" ON comments_log FOR SELECT USING (workspace_id IN (SELECT get_my_workspace_ids()));
CREATE POLICY "workspace_dms" ON dm_log FOR SELECT USING (workspace_id IN (SELECT get_my_workspace_ids()));
CREATE POLICY "workspace_leads" ON leads FOR ALL USING (workspace_id IN (SELECT get_my_workspace_ids()));
CREATE POLICY "workspace_links" ON short_links FOR ALL USING (workspace_id IN (SELECT get_my_workspace_ids()));
CREATE POLICY "workspace_subs" ON subscriptions FOR SELECT USING (workspace_id IN (SELECT get_my_workspace_ids()));
CREATE POLICY "workspace_payments" ON payments FOR SELECT USING (workspace_id IN (SELECT get_my_workspace_ids()));
